class Solution {
public:
    int maxSum(vector<int>& nums, int k) {
        long long mod = 1e9 + 7;
        vector<int> cnt(31, 0);
        for (int x : nums) {
            for (int i = 0; i < 31; i++) {
                if ((x >> i) & 1) cnt[i]++;
            }
        }
        long long ans = 0;
        for (int step = 0; step < k; step++) {
            long long val = 0;
            for (int i = 0; i < 31; i++) {
                if (cnt[i] > 0) {
                    val |= (1LL << i);
                    cnt[i]--;
                }
            }
            ans = (ans + val * val) % mod;
        }
        return ans;
    }
};

class Solution {
    public int maxSum(List<Integer> nums, int k) {
        long mod = 1_000_000_007L;
        int[] cnt = new int[31];
        for (int x : nums) {
            for (int i = 0; i < 31; i++) {
                if (((x >> i) & 1) == 1) cnt[i]++;
            }
        }
        long ans = 0;
        for (int step = 0; step < k; step++) {
            long val = 0;
            for (int i = 0; i < 31; i++) {
                if (cnt[i] > 0) {
                    val |= (1L << i);
                    cnt[i]--;
                }
            }
            ans = (ans + val * val) % mod;
        }
        return (int) ans;
    }
}

