var maxSum = function(nums, k) {
    const mod = 1000000007n;
    const cnt = new Int32Array(31);
    for (const x of nums) {
        for (let i = 0; i < 31; i++) {
            if ((x >> i) & 1) cnt[i]++;
        }
    }
    let ans = 0n;
    for (let step = 0; step < k; step++) {
        let val = 0n;
        for (let i = 0; i < 31; i++) {
            if (cnt[i] > 0) {
                val |= (1n << BigInt(i));
                cnt[i]--;
            }
        }
        ans = (ans + val * val) % mod;
    }
    return Number(ans);
};
